public class TelemetryMiddleware
{
    private readonly RequestDelegate _next;
    private readonly IMeter _meter;
    private readonly Histogram<double> _latency;

    public TelemetryMiddleware(RequestDelegate next, IMeterFactory factory)
    {
        _next = next;
        _meter = factory.Create("app.http");
        _latency = _meter.CreateHistogram<double>("request.duration",
            unit: "ms");
    }

    public async Task InvokeAsync(HttpContext context)
    {
        var sw = Stopwatch.StartNew();
        try
        {
            await _next(context);
            _latency.Record(sw.Elapsed.TotalMilliseconds,
                new KeyValuePair<string, object?>
                    ("route", context.GetEndpoint()?.DisplayName),
                new KeyValuePair<string, object?>
                    ("status", context.Response.StatusCode));
        }
        catch (Exception ex)
        {
            _meter.CreateCounter<int>("request.errors").Add(1);
            throw;
        }
    }
}
